from pathlib import Path
import base64

PATH = Path("components/portal/mobile-portal-navigation.tsx")

if not PATH.exists():
    raise SystemExit(
        "Missing components/portal/mobile-portal-navigation.tsx. "
        "Run this after the Mobile App Shell Phase 1 patch."
    )

current = PATH.read_text(encoding="utf-8")

if 'const moreEntries: NavEntry[]' not in current:
    raise SystemExit(
        "Unexpected mobile navigation state. "
        "This patch expects the Phase 1 mobile shell working tree."
    )

replacement = base64.b64decode("").decode("utf-8")

PATH.write_text(
    replacement,
    encoding="utf-8",
)

print("✓ components/portal/mobile-portal-navigation.tsx")
print("")
print("Mobile navigation completed.")
print("No SQL and no npm install required.")
print("Run: npm run build")
